])

# Apply: if val in 1-4, add 6, cap at 9
def new_val(v):
    if v == 0 or v == 5:
        return v
    elif v < 5:
        return min(v + 6, 9)
    else:
        return 9  # cap for v >= 5

result = np.zeros_like(grid, dtype=int)
for i in range(2):
    for j in range(20):
        result[i, j] = new_val(grid[i, j])

print("Result:")
print(result)
print("\nAs list:")
print(result.tolist())

